"""Report the benchmark artifact directories generated by the PoC harness."""

from __future__ import annotations

from pathlib import Path


def main() -> None:
    artifacts = Path("artifacts")
    runs = sorted(artifacts.glob("*/manifest.json")) if artifacts.exists() else []
    print(f"Scheduler wake-up PoC reports found: {len(runs)}")
    for run in runs:
        print(run)


if __name__ == "__main__":
    main()
